  var mask = tile.wangEdgeMask;
  if (mask === undefined) mask = 0;
  if (tile.transitionPair) {
    // Mask 0-15 directly indexes the Wang tile for from-side tiles.
    // For to-side tiles, invert bits (XOR 15) because the tileset is
    // laid out from the from-biome's perspective.
    var transitionMask = tile.transitionSide === 'to' ? (mask ^ 15) : mask;
