const TERRAIN_RENDER_VERSION = 'wang-corner-v17';

// Corner-to-wang lookup for PixelLab 16-tile Wang sets.
// Each tile's 4 corners sample from adjacent map cells:
//   NW = tile, NE = E neighbor, SW = S neighbor, SE = SE neighbor
// Corner mask bits: NW=8, NE=4, SW=2, SE=1 (bit set when corner is "from" biome)
const CORNER_TO_WANG = [
  12,  // 0b0000 = all "to" biome → to-side interior (wang_12)
  13,  // 0b0001 = SE is "from"
   0,  // 0b0010 = SW is "from"
   3,  // 0b0011 = SW+SE
   8,  // 0b0100 = NE is "from"
   1,  // 0b0101 = NE+SE
  14,  // 0b0110 = NE+SW
   5,  // 0b0111 = NE+SW+SE
  15,  // 0b1000 = NW is "from"
   4,  // 0b1001 = NW+SE
  11,  // 0b1010 = NW+SW
   2,  // 0b1011 = NW+SW+SE
   9,  // 0b1100 = NW+NE
  10,  // 0b1101 = NW+NE+SE
   7,  // 0b1110 = NW+NE+SW
   6,  // 0b1111 = all "from" biome → from-side interior (wang_6)
